// SPDX-License-Identifier: MPL-2.0
//! The protocol's self-description: one table describing every method — its MCP tool name,
//! parameters, result, whether it mutates, and which permission it needs (specs/23 § 3–5).
//!
//! `agent.schema`, `agent.hello` and `regia mcp` all read this table, so the MCP tool list and
//! the protocol schema can never drift apart.

use serde_json::{Value, json};

/// Which permission a method needs (`docs/specs/23-agent-native.md` § 5).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Permission {
    /// Read-only queries; always allowed.
    Read,
    /// Creating, changing or removing scene content.
    EditScene,
    /// Driving the running game: pause/step/resume, time scale, input injection, waiting.
    Play,
    /// Loading and reloading assets.
    Assets,
    /// Launching, stopping and driving out-of-process editor tools (ADR-1523). Not in the
    /// default profile: a project grants it in `.regia/agent.toml`, and a tool's scope never can.
    Tools,
    /// Changing which native code loads (`plugin.enable`, `plugin.disable`, `plugin.reload`;
    /// `specs/23` § 5 calls this class code execution). Not in the default profile, and a tool's
    /// scope never holds it.
    Build,
    /// Accepting staged changes (`review.accept`, specs/23 § 5, ADR-2346): writing an agent's
    /// proposed files into the project. Not in the default profile, and a tool's scope never holds
    /// it, so an agent cannot approve its own proposals; the editor's Agent Changes panel decides
    /// in-process.
    Review,
}

impl Permission {
    /// The name used in `.regia/agent.toml`'s `permissions` list.
    pub fn name(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::EditScene => "edit_scene",
            Self::Play => "play",
            Self::Assets => "assets",
            Self::Tools => "tools",
            Self::Build => "build",
            Self::Review => "review",
        }
    }

    /// The permission named `name` in `.regia/agent.toml` (`read`, `edit_scene`, `play`,
    /// `assets`, `tools`, `build` or `review`).
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        [
            Self::Read,
            Self::EditScene,
            Self::Play,
            Self::Assets,
            Self::Tools,
            Self::Build,
            Self::Review,
        ]
        .into_iter()
        .find(|permission| permission.name() == name)
    }
}

/// One parameter of a method.
#[derive(Clone)]
pub struct ParamSchema {
    /// Parameter name.
    pub name: &'static str,
    /// JSON type (for example `"object"` or `"integer"`), a `|`-separated union, or `"any"`
    /// for no type restriction.
    pub kind: &'static str,
    /// Whether the call fails when the parameter is absent.
    pub required: bool,
    /// What the parameter does.
    pub description: &'static str,
}

/// One method of the protocol.
#[derive(Clone)]
pub struct MethodSchema {
    /// JSON-RPC method name, e.g. `scene.spawn`.
    pub name: &'static str,
    /// MCP tool name, e.g. `spawn`. Empty = protocol-only (no MCP tool).
    pub tool: &'static str,
    /// One-line description (also the MCP tool description).
    pub description: &'static str,
    /// Parameters.
    pub params: &'static [ParamSchema],
    /// What the successful result contains.
    pub result: &'static str,
    /// Whether the call changes engine state (rate-limited and permission-gated).
    pub mutating: bool,
    /// The permission the call needs.
    pub permission: Permission,
}

const fn p(name: &'static str, kind: &'static str, required: bool, description: &'static str) -> ParamSchema {
    ParamSchema {
        name,
        kind,
        required,
        description,
    }
}

/// User asset library schema shared with the editor host (ADR-8201).
pub const ASSET_LIBRARY_METHOD: MethodSchema = MethodSchema {
    name: "editor.asset_library",
    tool: "asset_library",
    description: "List the user's cross-project library, add an asset with dependencies, or use a copied entry in the project with fresh paths and IDs. Requires the editor; never links projects to the library.",
    params: &[
        p("action", "string", true, "list, add or use."),
        p(
            "path",
            "string",
            false,
            "For add: project-relative source under assets/.",
        ),
        p(
            "entry",
            "string",
            false,
            "For use: entry ID returned by list or add.",
        ),
    ],
    result: "list: {entries: [{entry, roots, assets}], errors}; add/use: {job}; agent.job_status result: add {entry, roots, assets}, use {roots, paths, imported}",
    mutating: true,
    permission: Permission::Assets,
};

