impl MethodSchema {
    /// The JSON Schema of the method's params (an object schema).
    pub fn params_json_schema(&self) -> Value {
        self.params_json_schema_with(&|param| {
            if self.name == "render.out_start" {
                crate::render_out::param_shape(param)
            } else {
                None
            }
        })
    }

    /// Like [`Self::params_json_schema`], with `shape_of(param)` giving a param's own JSON
    /// Schema (an array of tagged items, an enum) in place of the bare type.
    pub fn params_json_schema_with(&self, shape_of: &dyn Fn(&str) -> Option<Value>) -> Value {
        let mut properties = serde_json::Map::new();
        let mut required = Vec::new();
        for param in self.params {
            let mut shape = shape_of(param.name).unwrap_or_else(|| match param.kind {
                "any" => json!({}),
                kind if kind.contains('|') => json!({ "type": kind.split('|').collect::<Vec<_>>() }),
                kind => json!({ "type": kind }),
            });
            shape["description"] = param.description.into();
            properties.insert(param.name.into(), shape);
            if param.required {
                required.push(param.name);
            }
        }
        json!({
            "type": "object",
            "properties": properties,
            "required": required,
            "additionalProperties": false,
        })
    }

    /// The method as one entry of `regia://protocol/schema.json`. Built-in methods also carry
    /// their [`crate::contract::MethodContract`]: `example`, `errors`, `limits` and `cost`.
    pub fn to_json(&self) -> Value {
        self.to_json_with(&|param| {
            if self.name == "render.out_start" {
                crate::render_out::param_shape(param)
            } else {
                None
            }
        })
    }

    /// Like [`Self::to_json`], with `shape_of(param)` as in [`Self::params_json_schema_with`].
    pub fn to_json_with(&self, shape_of: &dyn Fn(&str) -> Option<Value>) -> Value {
        let mut entry = json!({
            "name": self.name,
            "tool": self.tool,
            "description": self.description,
            "params": self.params_json_schema_with(shape_of),
            "result": self.result,
            "mutating": self.mutating,
            "permission": self.permission.name(),
        });
        if let (Some(contract), Some(map)) = (crate::contract::contract(self.name), entry.as_object_mut())
            && let Value::Object(fields) = contract.to_json()
        {
            map.extend(fields);
        }
        entry
    }
}

/// Looks a method up by its JSON-RPC name.
pub fn method(name: &str) -> Option<&'static MethodSchema> {
    METHODS.iter().find(|m| m.name == name)
}

/// Looks a method up by its MCP tool name.
pub fn method_by_tool(tool: &str) -> Option<&'static MethodSchema> {
    METHODS.iter().find(|m| m.tool == tool)
}

/// The whole table as the `regia://protocol/schema.json` document. `limits` holds the
/// protocol-wide caps (ADR-1034); each method's own are in its entry.
pub fn schema_json() -> Value {
    json!({
        "protocol": crate::protocol::PROTOCOL_VERSION,
        "limits": protocol_limits_json(),
        "methods": METHODS.iter().map(MethodSchema::to_json).collect::<Vec<_>>(),
    })
}

/// `agent.schema { method? }`: the whole table, or one method's entry (`F0003` when unknown).
pub(crate) fn schema_call(
    params: &Value,
    extension: Option<&crate::extension::AgentExtension>,
    registered: Value,
) -> Result<Value, crate::protocol::RpcError> {
    let Some(name) = params.get("method") else {
        let mut table = schema_json();
        if let (Some(extension), Some(methods)) = (extension, table["methods"].as_array_mut()) {
            // The host's methods (the editor's) follow the built-in table; a built-in name wins.
            methods.extend(
                extension
                    .schema_entries()
                    .into_iter()
                    .filter(|entry| entry["name"].as_str().is_some_and(|name| method(name).is_none())),
            );
        }
        // Methods active extensions registered, with their provider (specs/57 § 5.2).
        table["extension_methods"] = registered;
        return Ok(table);
    };
    let name = name
        .as_str()
        .ok_or_else(|| crate::protocol::RpcError::invalid_params("`method` must be a method name string"))?;
    let entry = match method(name) {
        Some(entry) => entry.to_json(),
        None => extension
            .and_then(|extension| {
                let row = extension.method_schema(name)?;
                Some(row.to_json_with(&|param| extension.param_shape(row.name, param).cloned()))
            })
            .or_else(|| {
                registered
                    .as_array()?
                    .iter()
                    .find(|row| row["name"].as_str() == Some(name))
                    .cloned()
            })
            .ok_or_else(|| {
                crate::protocol::RpcError::not_found(
                    format!("no method {}", name.chars().take(128).collect::<String>()),
                    "agent.schema without params lists every method",
                )
            })?,
    };
    Ok(json!({
        "protocol": crate::protocol::PROTOCOL_VERSION,
        "limits": protocol_limits_json(),
        "methods": [entry],
    }))
}

/// The caps every call shares: the default array and string sizes, the universal error codes,
/// and where the rate limits come from.
fn protocol_limits_json() -> Value {
    json!({
        "max_items": crate::contract::DEFAULT_MAX_ITEMS,
        "max_string_bytes": crate::contract::DEFAULT_MAX_BYTES,
        "universal_errors": crate::contract::UNIVERSAL_ERRORS,
        "rate": "mutating calls: rate_limit_per_second (default 50); cost \"heavy\" calls: heavy_rate_limit_per_second (default 60); both in .regia/agent.toml",
    })
}

/// Every method name, sorted, as `agent.hello` reports them.
pub fn method_names() -> Vec<&'static str> {
    let mut names: Vec<_> = METHODS.iter().map(|m| m.name).collect();
    names.sort_unstable();
    names
}

/// Editor viewport overlay contract (ADR-8199); runtime-only hosts return `editor_not_running`.
pub const VIEWPORT_OVERLAYS: MethodSchema = MethodSchema {
    name: "editor.viewport_overlays",
    tool: "viewport_overlays",
    description: "Read or change per-user viewport overlays and named presets. Layout changes never resize the pane or edit the scene. Outside the editor: editor_not_running.",
    params: &[
        p(
            "action",
            "string",
            false,
            "get (default), set, reset, preset_save, preset_apply or preset_delete.",
        ),
        p(
            "pane",
            "string",
            false,
            "View kind: perspective (default), top, front, side, bottom, back or opposite_side. Shared by main and instance panes of that kind.",
        ),
        p(
            "group",
            "string",
            false,
            "For set or reset: transform, snap, camera, view_show, tools or select.",
        ),
        p(
            "dock",
            "string",
            false,
            "For set: top, bottom, left, right or floating.",
        ),
        p(
            "position",
            "array",
            false,
            "For set: normalized [x,y], finite and in 0..1. Along the dock edge, or within the pane when floating.",
        ),
        p(
            "collapsed",
            "boolean",
            false,
            "For set: collapse to an accessible icon menu.",
        ),
        p(
            "vertical",
            "boolean",
            false,
            "For set: arrange the group's controls vertically.",
        ),
        p(
            "name",
            "string",
            false,
            "Required by preset actions: trimmed name, 1..64 bytes, no control characters; up to 32 per pane kind. Saving an existing name replaces it.",
        ),
        p(
            "selection",
            "string",
            false,
            "For set: box or lasso; session selection shape, not included in overlay presets.",
        ),
    ],
    result: "{pane,groups:{group:{dock,position,collapsed,vertical}},presets:[name],selection}",
    // Layout and preset edits change per-user editor state. A read method cannot be mutating
    // (schema gate and the read-method audit). edit_scene is the default-profile write class;
    // the call still does not touch scene entities. `get` needs the same class as `set`.
    mutating: true,
    permission: Permission::EditScene,
};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_are_unique_and_tools_match() {
        let names = method_names();
        let mut tools: Vec<_> = METHODS
            .iter()
            .filter(|m| !m.tool.is_empty())
            .map(|m| m.tool)
            .collect();
        tools.sort_unstable();
        let tools_before = tools.clone();
        tools.dedup();
        assert_eq!(tools, tools_before, "tool names are unique");
        assert_eq!(names.len(), METHODS.len(), "method names are unique");
        for m in METHODS {
            assert!(!m.description.is_empty(), "{} described", m.name);
            assert!(!m.result.is_empty(), "{} has a result shape", m.name);
            assert!(
                !m.mutating || m.permission != Permission::Read,
                "{} mutating needs a permission",
                m.name
            );
            assert_eq!(m.name.split('.').count(), 2, "{} is <area>.<name>", m.name);
        }
    }

    /// `seeing.compare` always adds `psnr_db`, `aov` and `mime` on the default mode.
    #[test]
    fn seeing_compare_result_names_psnr_aov_and_mime() {
        let result = method("seeing.compare").expect("method").result;
        for field in ["psnr_db", "aov", "mime"] {
            assert!(result.contains(field), "{result}");
        }
    }

    #[test]
    fn lookups_agree() {
        assert_eq!(method("scene.spawn").map(|m| m.tool), Some("spawn"));
        assert_eq!(method_by_tool("spawn").map(|m| m.name), Some("scene.spawn"));
        assert!(method("scene.nope").is_none());
        assert!(method_by_tool("nope").is_none());
    }

    #[test]
    fn terrain_stroke_schema_names_noise_and_ramp() {
        let stroke = method("terrain.stroke").expect("terrain.stroke");
        let mode = stroke
            .params
            .iter()
            .find(|param| param.name == "mode")
            .expect("mode");
        assert!(mode.description.contains("noise"), "mode lists noise");
        assert!(mode.description.contains("ramp"), "mode lists ramp");
        for name in ["wavelength", "seed", "from_height", "to_height"] {
            assert!(
                stroke.params.iter().any(|param| param.name == name),
                "terrain.stroke missing {name}"
            );
        }
        let wavelength = stroke
            .params
            .iter()
            .find(|param| param.name == "wavelength")
            .expect("wavelength");
        assert!(wavelength.description.contains("8 samples"));
        assert!(!wavelength.required);
    }

    #[test]
    fn control_op_descriptions_match_the_handlers() {
        // The `op` description must list exactly the ops the handler accepts:
        // `state_tree::control` takes pause/resume/restart (no step); `logic::control`
        // also takes step. Pinned after the two rows were accidentally swapped.
        let statetree_op = method("statetree.control")
            .and_then(|m| m.params.iter().find(|p| p.name == "op"))
            .map(|p| p.description)
            .expect("statetree.control op");
        assert_eq!(statetree_op, "pause, resume or restart.");
        let logic_op = method("logic.control")
            .and_then(|m| m.params.iter().find(|p| p.name == "op"))
            .map(|p| p.description)
            .expect("logic.control op");
        assert_eq!(
            logic_op,
            "pause, resume, restart, or step (run one more tick, then pause)."
        );
    }

    #[test]
    fn schema_entries_carry_the_method_contract() {
        let doc = schema_json();
        assert_eq!(doc["limits"]["max_items"], crate::contract::DEFAULT_MAX_ITEMS);
        for entry in doc["methods"].as_array().into_iter().flatten() {
            let name = entry["name"].as_str().unwrap_or_default();
            assert!(entry["example"].is_object(), "{name} example");
            assert!(entry["errors"].is_array(), "{name} errors");
            assert!(entry["limits"].is_array(), "{name} limits");
            assert!(
                matches!(entry["cost"].as_str(), Some("light" | "heavy")),
                "{name} cost"
            );
        }
        let one = schema_call(&json!({ "method": "play.step" }), None, Value::Null).expect("one method");
        let methods = one["methods"].as_array().cloned().unwrap_or_default();
        assert_eq!(methods.len(), 1);
        assert_eq!(methods[0]["name"], "play.step");
        assert_eq!(methods[0]["limits"][0]["param"], "frames");
        assert!(schema_call(&json!({ "method": "play.nope" }), None, Value::Null).is_err());
        assert!(schema_call(&json!({ "method": 5 }), None, Value::Null).is_err());
        assert_eq!(
            schema_call(&json!({}), None, Value::Null).expect("whole table")["methods"]
                .as_array()
                .map(Vec::len),
            Some(METHODS.len())
        );
    }

    #[test]
    fn schema_json_lists_every_method() {
        let doc = schema_json();
        let listed = doc["methods"].as_array().map(Vec::len).unwrap_or(0);
        assert_eq!(listed, METHODS.len());
        assert_eq!(doc["protocol"], crate::protocol::PROTOCOL_VERSION);
    }

    #[test]
    fn union_parameter_kinds_export_primitive_type_arrays() {
        for (name, param, expected) in [
            ("voice_chat.mute", "target", json!(["string", "object"])),
            ("ragdoll.active_set", "strength", json!(["number", "object"])),
            ("ragdoll.active_set", "recovery", json!(["string", "object"])),
        ] {
            let table = schema_call(&json!({ "method": name }), None, Value::Null).expect("schema");
            assert_eq!(
                table["methods"][0]["params"]["properties"][param]["type"], expected,
                "{name}.{param}"
            );
            let schema = method(name).expect("method").params_json_schema();
            assert_eq!(
                schema["properties"][param]["type"], expected,
                "MCP schema for {name}.{param}"
            );
        }
    }

    #[test]
    fn params_schema_is_valid_json_schema() {
        for m in METHODS {
            let schema = m.params_json_schema();
            assert_eq!(schema["type"], "object", "{}", m.name);
            let required = schema["required"].as_array().map(Vec::len).unwrap_or(0);
            let props = schema["properties"].as_object().map(|p| p.len()).unwrap_or(0);
            assert!(required <= props, "{}: required ⊆ properties", m.name);
            for param in m.params {
                let primitive = |kind: &Value| {
                    matches!(
                        kind.as_str(),
                        Some("null" | "boolean" | "object" | "array" | "number" | "string" | "integer")
                    )
                };
                let property = &schema["properties"][param.name];
                match property.get("type") {
                    None => assert_eq!(
                        param.kind, "any",
                        "{}.{} has no type restriction",
                        m.name, param.name
                    ),
                    Some(Value::Array(kinds)) => assert!(
                        !kinds.is_empty() && kinds.iter().all(primitive),
                        "{}.{} has an invalid type union: {kinds:?}",
                        m.name,
                        param.name
                    ),
                    Some(kind) => assert!(
                        primitive(kind),
                        "{}.{} has an invalid type: {kind}",
                        m.name,
                        param.name
                    ),
                }
            }
        }
    }
}
